 void renderChats(){
  if(!screen.equals("home"))return;list.removeAllViews();
  for(int i=0;i<chats.length();i++){
   JSONObject c=chats.optJSONObject(i);String title=c.optString("title","Чат");
   if((!filter.isEmpty()&&!filter.equals(c.optString("kind")))||!title.toLowerCase(Locale.ROOT).contains(search.toLowerCase(Locale.ROOT)))continue;
   LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(10),dp(10),dp(10),dp(10));row.setBackground(bg(CARD));
   avatar(row,title,c.optJSONObject("peer")==null?0:c.optJSONObject("peer").optInt("id"));
   LinearLayout text=new LinearLayout(this);text.setOrientation(1);TextView name=label(title,17);name.setSingleLine(true);name.setEllipsize(android.text.TextUtils.TruncateAt.END);text.addView(name);
   String preview=c.optString("last_message","");TextView snippet=label(preview.equals("null")?"Начните разговор":preview,13);snippet.setTextColor(0xff9baec7);snippet.setMaxLines(1);snippet.setEllipsize(android.text.TextUtils.TruncateAt.END);text.addView(snippet);row.addView(text,new LinearLayout.LayoutParams(0,-2,1));
   if(c.optInt("unread")>0){TextView badge=label(""+c.optInt("unread"),13);badge.setBackground(bg(0xff31527b));row.addView(badge);}
   row.setOnClickListener(v->open(c,false));add(list,row);
  }
  if(list.getChildCount()==0)add(list,label("Здесь появятся ваши разговоры",16));
 }
 void avatar(LinearLayout row,String title,int id){
  FrameLayout frame=new FrameLayout(this);frame.setBackground(bg(0xff2b4262));frame.setClipToOutline(true);
  TextView initials=label(title.isEmpty()?"?":title.substring(0,1).toUpperCase(Locale.ROOT),24);initials.setGravity(Gravity.CENTER);initials.setTextColor(ACCENT);frame.addView(initials,new FrameLayout.LayoutParams(-1,-1));
  ImageView image=new ImageView(this);image.setScaleType(ImageView.ScaleType.CENTER_CROP);frame.addView(image,new FrameLayout.LayoutParams(-1,-1));row.addView(frame,new LinearLayout.LayoutParams(dp(54),dp(54)));
  if(id<=0||noAvatar.contains(id))return;if(avatars.containsKey(id)){image.setImageBitmap(avatars.get(id));return;}
  int g=generation;String base=api.base,cookie=api.cookie();images.execute(()->{if(!alive||g!=generation)return;java.net.HttpURLConnection c=null;android.graphics.Bitmap bitmap=null;try{c=(java.net.HttpURLConnection)new java.net.URL(base+"avatar.php?id="+id).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(5000);c.setReadTimeout(5000);c.setRequestProperty("Cookie",cookie);if(c.getResponseCode()==200){ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(out.size()+n>1048576)throw new IOException();out.write(b,0,n);}}byte[] bytes=out.toByteArray();bitmap=android.graphics.BitmapFactory.decodeByteArray(bytes,0,bytes.length);}}catch(Exception ignored){}finally{if(c!=null)c.disconnect();}android.graphics.Bitmap result=bitmap;handler.post(()->{if(!alive||g!=generation)return;if(result!=null){if(avatars.size()>=100)avatars.clear();avatars.put(id,result);image.setImageBitmap(result);}else noAvatar.add(id);});});
 }
 void refresh(boolean first){if(polling)return;polling=true;int g=generation,id=chatId;boolean admin=adminChat;String ids=android.text.TextUtils.join(",",messages.keySet());int after=messages.isEmpty()?0:messages.lastKey();worker.execute(()->{try{JSONObject d=admin?api.admin("chat.messages&chat_id="+id,null):api.get(id>0?"sync&chat_id="+id+"&after="+(first?0:after)+"&known_ids="+NativeApi.enc(ids):"sync");handler.post(()->{polling=false;if(!alive||g!=generation)return;error.setVisibility(View.GONE);if(d.has("chats"))chats=d.optJSONArray("chats");if(screen.equals("home"))renderChats();else{boolean changed=first;JSONArray rows=d.optJSONArray("messages"),removed=d.optJSONArray("removed_ids");if(admin){messages.clear();changed=true;}if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject m=rows.optJSONObject(i);if(!messages.containsKey(m.optInt("id")))changed=true;messages.put(m.optInt("id"),m);}if(removed!=null)for(int i=0;i<removed.length();i++)if(messages.remove(removed.optInt(i))!=null)changed=true;room=d.optJSONObject("active_call");if(!admin&&d.has("bot_keyboard"))applyBotKeyboard(d.optJSONObject("bot_keyboard"));join.setVisibility(room!=null&&!CallService.active?View.VISIBLE:View.GONE);if(changed)renderMessages();if(!admin&&!messages.isEmpty()){int last=messages.lastKey();worker.execute(()->{try{api.post("chat.read",NativeApi.json("chat_id",id,"last_id",last));}catch(Exception ignored){}});}}});}catch(Exception e){handler.post(()->{polling=false;if(alive&&g==generation){if(e instanceof MobileApi.Error&&((MobileApi.Error)e).code==401&&user!=null){user=null;stopService(new Intent(this,InboxService.class));auth(false);}error.setText(e.getMessage());error.setVisibility(View.VISIBLE);}});}});}
