 void showLongTextPage(String text,int offset){int start=offset>0&&offset<text.length()&&Character.isLowSurrogate(text.charAt(offset))&&Character.isHighSurrogate(text.charAt(offset-1))?offset-1:offset;int end=Math.min(text.length(),start+8192);if(end<text.length()&&Character.isHighSurrogate(text.charAt(end-1))&&Character.isLowSurrogate(text.charAt(end)))end--;int next=end;ScrollView pane=new ScrollView(this);pane.addView(label(text.substring(start,end),16));AlertDialog.Builder dialog=new AlertDialog.Builder(this).setTitle("Текст сообщения").setView(pane).setNegativeButton("Закрыть",null);if(end<text.length())dialog.setPositiveButton("Далее",(d,w)->showLongTextPage(text,next));if(start>0)dialog.setNeutralButton("Назад",(d,w)->showLongTextPage(text,Math.max(0,start-8192)));dialog.show();}
