 void sendText(String text,boolean clearComposer){if(text.isEmpty()||sending)return;if(text.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>10*1024*1024){toast("Текст превышает 10 МиБ");return;}if(!text.equals(pendingBody)){pendingBody=text;pendingNonce=UUID.randomUUID().toString();}sending=true;boolean admin=adminChat;int id=chatId;JSONObject data=NativeApi.json("chat_id",id,"body",text,"nonce",pendingNonce);job(()->{try{return admin?api.admin("chat.send",data):api.post("message.send",data);}finally{handler.post(()->sending=false);}},d->{if(clearComposer&&composer!=null&&composer.getText().toString().trim().equals(text))composer.setText("");pendingBody="";pendingNonce="";if(chatId==id&&activeReplyKeyboard!=null&&activeReplyKeyboard.optBoolean("one_time_keyboard")){replyKeyboardCollapsed=true;renderBotKeyboard();}refresh(false);});}
