 void handle(Intent intent){if(intent==null||user==null)return;String token=intent.getStringExtra("token"),action=intent.getAction();if(token!=null){if("accept-call".equals(action))call(token,"api.php",false);else if("incoming-call".equals(action)&&token.equals(InboxService.ringingToken))new AlertDialog.Builder(this).setTitle(InboxService.ringingName).setMessage("Входящий звонок").setPositiveButton("Принять",(d,w)->{if(token.equals(InboxService.ringingToken))call(token,"api.php",false);}).setNegativeButton("Отклонить",(d,w)->startService(new Intent(this,InboxService.class).putExtra("command","decline").putExtra("token",token))).show();}int id=intent.getIntExtra("chat_id",0);if(id>0){getSystemService(NotificationManager.class).cancel("chat",id);load(id);}intent.removeExtra("token");intent.removeExtra("chat_id");if(Intent.ACTION_VIEW.equals(action)&&intent.getData()!=null){String link=intent.getData().toString();intent.setData(null);joinLink(link);}showCall();}
